#[no_mangle]
pub extern "C" fn kahn(v:*const i64,n:usize)->i64{if v.is_null()||n<2||n>258{return -2;}let v=unsafe{std::slice::from_raw_parts(v,n)};let nv=v[0];let ne=v[1];if !(0..=32).contains(&nv)||!(0..=128).contains(&ne)||n!=2+2*ne as usize{return -2;}let mut adj=[[false;32];32];let mut ind=[0i64;32];for i in 0..ne as usize{let a=v[2+2*i];let b=v[3+2*i];if a<0||a>=nv||b<0||b>=nv{return -2;}if !adj[a as usize][b as usize]{adj[a as usize][b as usize]=true;ind[b as usize]+=1;}}let mut q=[0usize;32];let(mut head,mut tail)=(0,0);for i in 0..nv as usize{if ind[i]==0{q[tail]=i;tail+=1;}}while head<tail{let x=q[head];head+=1;for y in 0..nv as usize{if adj[x][y]{ind[y]-=1;if ind[y]==0{q[tail]=y;tail+=1;}}}}if tail==nv as usize{nv}else{-1}}
